PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?a ?k2 ?ka ?ln ?o ?s ?third WHERE { ?s ex:age ?a . ?s ex:knows ?o . OPTIONAL { ?s ex:name ?ln FILTER (lang(?ln) = "uk") } BIND (?a / 3 AS ?third) OPTIONAL { ?s ex:knows ?k2 . ?k2 ex:age ?ka FILTER (?ka > ?a) } }

PREFIX ex: <http://example.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?a ?a2x ?oldest ?s WHERE { ?s a ex:Person . ?s ex:age ?a . BIND (?a * 2 AS ?a2x) FILTER NOT EXISTS { ?s ex:email ?x } { SELECT (MAX(?ma) AS ?oldest) WHERE { ?p ex:age ?ma } } }

