PREFIX ex: <http://example.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?a ?a2x ?dist ?n ?os ?s WHERE { ?s ex:name ?n . ?s ex:age ?a . BIND (ABS(?a - 40) AS ?dist) BIND (?a * 2 AS ?a2x) OPTIONAL { { ?s ex:score ?os FILTER (?os > 5) } } }

